import { Box, Flex, HStack, IconButton, Menu, Stack, Text } from "@chakra-ui/react";
import {
  GitCommitHorizontal,
  MessageCircleIcon,
  Minus,
  PanelRightClose,
  PenBox,
  SquareArrowOutDownLeft,
} from "lucide-react";
import type { ReactNode } from "react";
import { ChatInput, ConversationMessages, generateEditorStateFromString, type UIMessage } from "@/components/chat-ui";
import { type Diff, DiffDrawer } from "@/components/diff-drawer";
import { EmptyState } from "@/components/empty-state";
import { HorizontalMenuStack } from "@/components/horizontal-menu-stack";
import { MenuItem } from "@/components/menu-item";
import { Tooltip } from "@/components/tooltip";
import { SessionBrowserMenu, type SessionBrowserMenuProps } from "./session-browser";
import { WorkspacePanelHeader } from "./workspace-panel-header";

const EMPTY_PROMPT_STATE = JSON.stringify(generateEditorStateFromString(""));
const SESSION_LIST_WIDTH = "18rem";
const DEFAULT_SESSION_LIST_TITLE = "All sessions";
const DEFAULT_SESSION_LIST_EMPTY_LABEL = "No sessions yet";
const DEFAULT_SESSION_LIST_CLOSE_LABEL = "Close sessions list";

interface WorkspacePanelDockProps {
  width: string;
  messages: UIMessage[];
  streaming?: boolean;
  sessionMenu?: SessionBrowserMenuProps;
  chatInputPlaceholder: string;
  emptyStateTitle: string;
  emptyStateDescription: string;
  onSubmitMessage?: (text: string, attachments: string[]) => void;
  onCollapse: () => void;
  onClose: () => void;
  onCommit?: () => void;
  onCreateSession?: () => void;
  newSessionLabel?: string;
  leadingActions?: ReactNode;
  footerActions?: ReactNode;
  diffs: Diff[];
  commitLabel?: string;
  collapseLabel?: string;
  closeLabel?: string;
  isSessionListOpen?: boolean;
  onCloseSessionList?: () => void;
  sessionListTitle?: string;
  sessionListEmptyLabel?: string;
  sessionListCloseLabel?: string;
}

function SessionListPanel(props: {
  menu?: SessionBrowserMenuProps;
  title: string;
  emptyLabel: string;
  closeLabel: string;
  onClose?: () => void;
}) {
  const { menu, title, emptyLabel, closeLabel, onClose } = props;
  const items = menu?.items ?? [];

  return (
    <Stack
      h="full"
      minH="0"
      w={SESSION_LIST_WIDTH}
      minW={SESSION_LIST_WIDTH}
      borderRightWidth="1px"
      bg="background.primary"
      data-testid="workspace-panel-session-list"
    >
      <HorizontalMenuStack alignItems="center" gap="sm" px="sm" py="xs" borderBottomWidth="1px">
        <Text textStyle="label/S/medium" color="foreground.primary">
          {title}
        </Text>
        <Tooltip content={closeLabel}>
          <IconButton size="xs" variant="ghost" aria-label={closeLabel} onClick={onClose}>
            <PanelRightClose size={16} />
          </IconButton>
        </Tooltip>
      </HorizontalMenuStack>
      <Stack flex="1" minH="0" overflowY="auto" gap="xs" px="xs" py="xs">
        {items.length === 0 ? (
          <Text textStyle="label/XS/regular" color="foreground.secondary" px="xs" py="xs">
            {menu?.emptyLabel ?? emptyLabel}
          </Text>
        ) : (
          items.map((item) => (
            <Menu.Root key={item.id}>
              <MenuItem
                primaryLabel={item.primaryLabel}
                tooltipLabel={item.tooltipLabel}
                variant="compact"
                isSelected={item.isSelected}
                isDisabled={item.isDisabled}
                onClick={item.onSelect}
              />
            </Menu.Root>
          ))
        )}
      </Stack>
    </Stack>
  );
}

export const WorkspacePanelDock = (props: WorkspacePanelDockProps) => {
  const {
    width,
    messages,
    streaming = false,
    sessionMenu,
    chatInputPlaceholder,
    emptyStateTitle,
    emptyStateDescription,
    onSubmitMessage,
    onCollapse,
    onClose,
    onCommit,
    onCreateSession,
    newSessionLabel = "New session",
    leadingActions,
    footerActions,
    diffs,
    commitLabel = "Commit",
    collapseLabel = "Collapse",
    closeLabel = "Close",
    isSessionListOpen = false,
    onCloseSessionList,
    sessionListTitle = DEFAULT_SESSION_LIST_TITLE,
    sessionListEmptyLabel = DEFAULT_SESSION_LIST_EMPTY_LABEL,
    sessionListCloseLabel = DEFAULT_SESSION_LIST_CLOSE_LABEL,
  } = props;
  const hasDiffs = diffs.length > 0;

  return (
    <Stack
      position="fixed"
      right="0"
      top="0"
      bottom="0"
      w={width}
      maxW="100vw"
      bg="background.primary"
      zIndex="docked"
      boxShadow="2xl"
      gap="0"
    >
      <WorkspacePanelHeader
        minH="49px"
        borderBottomWidth="1px"
        px="sm"
        py="xs"
        leftActions={
          <>
            <SessionBrowserMenu menu={sessionMenu} />
            <Tooltip content={newSessionLabel}>
              <IconButton size="xs" variant="ghost" aria-label={newSessionLabel} onClick={onCreateSession}>
                <PenBox size={16} />
              </IconButton>
            </Tooltip>
          </>
        }
        rightActions={
          <>
            <Tooltip content={commitLabel}>
              <IconButton size="xs" variant="ghost" aria-label={commitLabel} onClick={onCommit} disabled={!onCommit}>
                <GitCommitHorizontal size={16} />
              </IconButton>
            </Tooltip>
            <Tooltip content={collapseLabel}>
              <IconButton size="xs" variant="ghost" aria-label={collapseLabel} onClick={onCollapse}>
                <SquareArrowOutDownLeft size={16} />
              </IconButton>
            </Tooltip>
            <Tooltip content={closeLabel}>
              <IconButton size="xs" variant="ghost" aria-label={closeLabel} onClick={onClose}>
                <Minus size={16} />
              </IconButton>
            </Tooltip>
          </>
        }
      />

      <HStack h="full" gap="0" alignItems="stretch" minH="0">
        {isSessionListOpen ? (
          <SessionListPanel
            menu={sessionMenu}
            title={sessionListTitle}
            emptyLabel={sessionListEmptyLabel}
            closeLabel={sessionListCloseLabel}
            onClose={onCloseSessionList}
          />
        ) : null}

        <Stack h="full" flex="1" minW="0" px="md" py="sm" data-testid="workspace-panel-chat">
          <Flex position="relative" direction="column" w="full" h="full" overflow="hidden">
            <ConversationMessages
              messages={messages}
              streaming={streaming}
              placeholder={
                <EmptyState
                  icon={<MessageCircleIcon size={48} strokeWidth={1.5} />}
                  title={emptyStateTitle}
                  description={emptyStateDescription}
                />
              }
            />
            <ChatInput
              placeholder={chatInputPlaceholder}
              defaultState={EMPTY_PROMPT_STATE}
              streaming={streaming}
              onSubmit={onSubmitMessage}
              leadingActions={leadingActions}
            />
            <Flex mt="2xs" justifyContent="flex-end">
              {footerActions}
            </Flex>
          </Flex>
        </Stack>

        {hasDiffs ? (
          <Box
            h="full"
            minH="0"
            flex="1"
            minW="0"
            borderLeftWidth="1px"
            bg="bg.subtle"
            data-testid="workspace-panel-diff-panel"
          >
            <DiffDrawer diffs={diffs} />
          </Box>
        ) : null}
      </HStack>
    </Stack>
  );
};

