import { Box, Flex, IconButton } from "@chakra-ui/react";
import { Brain, Code2, FolderGit2, GitBranch, MessageCircleIcon, PenBox } from "lucide-react";
import { useEffect, useState } from "react";
import { ChatInput, ConversationMessages, generateEditorStateFromString, type UIMessage } from "@/components/chat-ui";
import { DiffBubble } from "@/components/chat-ui/components/diff-bubble";
import type { Diff } from "@/components/diff-drawer";
import { EmptyState } from "@/components/empty-state";
import { Tooltip } from "@/components/tooltip";
import { WorkspaceExecutorMenu } from "./executor-browser";
import { WorkspaceRepoMenu } from "./repo-browser";
import { SessionBrowserMenu, type SessionBrowserMenuProps } from "./session-browser";
import { WorkspacePanelBubble } from "./workspace-panel-bubble";
import { WorkspacePanelButton } from "./workspace-panel-button";
import { WorkspacePanelDock } from "./workspace-panel-dock";
import type { WorkspacePanelMenuOption } from "./workspace-panel-menu-option";

const EMPTY_PROMPT_STATE = JSON.stringify(generateEditorStateFromString(""));

const AGENT_OPTIONS = [
  { label: "Opencode", value: "opencode", icon: Code2 },
  { label: "Claude Code", value: "claude-code", icon: Code2 },
];

const REPOSITORY_OPTIONS = [
  { label: "schub", value: "schub", icon: FolderGit2 },
  { label: "dashboard", value: "dashboard", icon: FolderGit2 },
];

const BRANCH_OPTIONS = [
  { label: "main", value: "main", icon: GitBranch },
  { label: "feature/workspace-panel", value: "feature/workspace-panel", icon: GitBranch },
];

const MODEL_OPTIONS = [
  { label: "openai/gpt-5.3-codex", value: "openai/gpt-5.3-codex", icon: Brain },
  { label: "anthropic/claude-sonnet-4.5", value: "anthropic/claude-sonnet-4.5", icon: Brain },
];

export type WorkspacePanelMode = "closed" | "floating" | "docked";

export interface WorkspacePanelShellParameters {
  title: string;
  floatingPanelWidth: string;
  dockedPanelWidth: string;
  openTooltip: string;
  openButtonLabel: string;
  expandLabel: string;
  closeLabel: string;
  collapseLabel: string;
  newSessionLabel: string;
  commitLabel: string;
  sessionListTitle: string;
  sessionListCloseLabel: string;
  chatInputPlaceholder: string;
  emptyStateTitle: string;
  emptyStateDescription: string;
}

const DEFAULT_PANEL_PARAMETERS: WorkspacePanelShellParameters = {
  title: "Workspace panel",
  floatingPanelWidth: "38rem",
  dockedPanelWidth: "58rem",
  openTooltip: "Open chat",
  openButtonLabel: "Open workspace panel",
  expandLabel: "Expand",
  closeLabel: "Close",
  collapseLabel: "Collapse",
  newSessionLabel: "New session",
  commitLabel: "Commit",
  sessionListTitle: "All sessions",
  sessionListCloseLabel: "Close sessions list",
  chatInputPlaceholder: "Type a message...",
  emptyStateTitle: "No active conversations",
  emptyStateDescription: "Start a conversation to see messages here.",
};

interface WorkspacePanelShellProps {
  mode?: WorkspacePanelMode;
  initialMode?: WorkspacePanelMode;
  onModeChange?: (mode: WorkspacePanelMode) => void;
  messages?: UIMessage[];
  streaming?: boolean;
  sessionMenu?: SessionBrowserMenuProps;
  diffs?: Diff[];
  executorOptions?: WorkspacePanelMenuOption[];
  selectedExecutor?: string;
  onSelectExecutor?: (executor: string) => void;
  modelOptions?: WorkspacePanelMenuOption[];
  selectedModel?: string;
  onSelectModel?: (model: string) => void;
  repositoryOptions?: WorkspacePanelMenuOption[];
  selectedRepository?: string;
  onSelectRepository?: (repository: string) => void;
  branchOptions?: WorkspacePanelMenuOption[];
  selectedBranch?: string;
  onSelectBranch?: (branch: string) => void;
  isExecutorMenuDisabled?: boolean;
  isRepositoryMenuDisabled?: boolean;
  onSubmitMessage?: (text: string, attachments: string[]) => void;
  onCreateSession?: () => void;
  onCommit?: () => void;
  panelParameters?: Partial<WorkspacePanelShellParameters>;
}

export const WorkspacePanelShell = (props: WorkspacePanelShellProps) => {
  const {
    mode: controlledMode,
    initialMode = "closed",
    onModeChange,
    messages = [],
    streaming = false,
    sessionMenu,
    diffs = [],
    executorOptions,
    selectedExecutor,
    onSelectExecutor,
    modelOptions,
    selectedModel,
    onSelectModel,
    repositoryOptions,
    selectedRepository,
    onSelectRepository,
    branchOptions,
    selectedBranch,
    onSelectBranch,
    isExecutorMenuDisabled = false,
    isRepositoryMenuDisabled = false,
    onSubmitMessage,
    onCreateSession,
    onCommit,
    panelParameters,
  } = props;

  const resolvedPanelParameters = { ...DEFAULT_PANEL_PARAMETERS, ...panelParameters };
  const resolvedExecutorOptions = executorOptions ?? AGENT_OPTIONS;
  const resolvedModelOptions = modelOptions ?? MODEL_OPTIONS;
  const resolvedRepositoryOptions = repositoryOptions ?? REPOSITORY_OPTIONS;
  const resolvedBranchOptions = branchOptions ?? BRANCH_OPTIONS;
  const [uncontrolledMode, setUncontrolledMode] = useState<WorkspacePanelMode>(initialMode);
  const [isSessionListOpen, setIsSessionListOpen] = useState(false);
  const [uncontrolledSelectedAgent, setUncontrolledSelectedAgent] = useState(resolvedExecutorOptions[0]?.value ?? "");
  const [uncontrolledSelectedRepository, setUncontrolledSelectedRepository] = useState(
    resolvedRepositoryOptions[0]?.value ?? "",
  );
  const [uncontrolledSelectedBranch, setUncontrolledSelectedBranch] = useState(resolvedBranchOptions[0]?.value ?? "");
  const [uncontrolledSelectedModel, setUncontrolledSelectedModel] = useState(resolvedModelOptions[0]?.value ?? "");
  const mode = controlledMode ?? uncontrolledMode;
  const totalAdditions = diffs.reduce((acc, diff) => acc + (diff.additions ?? 0), 0);
  const totalDeletions = diffs.reduce((acc, diff) => acc + (diff.deletions ?? 0), 0);
  const resolvedSelectedAgent = selectedExecutor ?? uncontrolledSelectedAgent;
  const resolvedSelectedRepository = selectedRepository ?? uncontrolledSelectedRepository;
  const resolvedSelectedBranch = selectedBranch ?? uncontrolledSelectedBranch;
  const resolvedSelectedModel = selectedModel ?? uncontrolledSelectedModel;

  useEffect(() => {
    if (mode !== "docked") {
      setIsSessionListOpen(false);
    }
  }, [mode]);

  const setPanelMode = (nextMode: WorkspacePanelMode) => {
    if (controlledMode === undefined) {
      setUncontrolledMode(nextMode);
    }
    if (nextMode !== "docked") {
      setIsSessionListOpen(false);
    }
    onModeChange?.(nextMode);
  };

  const handleViewMoreSessions = () => {
    setIsSessionListOpen(true);
    if (mode !== "docked") {
      setPanelMode("docked");
    }
    sessionMenu?.onViewMore?.();
  };

  const resolvedSessionMenu = sessionMenu
    ? {
        ...sessionMenu,
        onViewMore: handleViewMoreSessions,
      }
    : undefined;

  const handleSelectAgent = (value: string) => {
    if (selectedExecutor === undefined) {
      setUncontrolledSelectedAgent(value);
    }
    onSelectExecutor?.(value);
  };

  const handleSelectModel = (value: string) => {
    if (selectedModel === undefined) {
      setUncontrolledSelectedModel(value);
    }
    onSelectModel?.(value);
  };

  const handleSelectRepository = (value: string) => {
    if (selectedRepository === undefined) {
      setUncontrolledSelectedRepository(value);
    }
    onSelectRepository?.(value);
  };

  const handleSelectBranch = (value: string) => {
    if (selectedBranch === undefined) {
      setUncontrolledSelectedBranch(value);
    }
    onSelectBranch?.(value);
  };

  const executorMenu = (
    <WorkspaceExecutorMenu
      executorOptions={resolvedExecutorOptions}
      selectedExecutor={resolvedSelectedAgent}
      onSelectExecutor={handleSelectAgent}
      modelOptions={resolvedModelOptions}
      selectedModel={resolvedSelectedModel}
      onSelectModel={handleSelectModel}
      isDisabled={isExecutorMenuDisabled}
    />
  );

  const repoMenu = (
    <WorkspaceRepoMenu
      repositoryOptions={resolvedRepositoryOptions}
      selectedRepository={resolvedSelectedRepository}
      onSelectRepository={handleSelectRepository}
      branchOptions={resolvedBranchOptions}
      selectedBranch={resolvedSelectedBranch}
      onSelectBranch={handleSelectBranch}
      isDisabled={isRepositoryMenuDisabled}
    />
  );

  return (
    <Box>
      {mode === "closed" ? (
        <Tooltip content={resolvedPanelParameters.openTooltip}>
          <WorkspacePanelButton
            aria-label={resolvedPanelParameters.openButtonLabel}
            onClick={() => setPanelMode("floating")}
          >
            <MessageCircleIcon size={20} strokeWidth={2} />
          </WorkspacePanelButton>
        </Tooltip>
      ) : null}

      <WorkspacePanelBubble
        width={resolvedPanelParameters.floatingPanelWidth}
        isOpen={mode === "floating"}
        title={resolvedPanelParameters.title}
        aria-label={resolvedPanelParameters.title}
        popOutLabel={resolvedPanelParameters.expandLabel}
        onClose={() => setPanelMode("closed")}
        onPopOut={() => setPanelMode("docked")}
        menu={
          <>
            <SessionBrowserMenu menu={resolvedSessionMenu} />
            {diffs.length > 0 ? <DiffBubble additions={totalAdditions} deletions={totalDeletions} /> : null}
            <Tooltip content={resolvedPanelParameters.newSessionLabel}>
              <IconButton
                size="xs"
                variant="ghost"
                aria-label={resolvedPanelParameters.newSessionLabel}
                onClick={onCreateSession}
              >
                <PenBox size={16} />
              </IconButton>
            </Tooltip>
          </>
        }
        closeLabel={resolvedPanelParameters.closeLabel}
      >
        <Flex position="relative" direction="column" w="full" h="full" overflow="hidden">
          <ConversationMessages
            messages={messages}
            streaming={streaming}
            placeholder={
              <EmptyState
                icon={<MessageCircleIcon size={48} strokeWidth={1.5} />}
                title={resolvedPanelParameters.emptyStateTitle}
                description={resolvedPanelParameters.emptyStateDescription}
              />
            }
          />
          <ChatInput
            placeholder={resolvedPanelParameters.chatInputPlaceholder}
            defaultState={EMPTY_PROMPT_STATE}
            streaming={streaming}
            onSubmit={onSubmitMessage}
            leadingActions={executorMenu}
          />
          <Flex mt="2xs" justifyContent="flex-end">
            {repoMenu}
          </Flex>
        </Flex>
      </WorkspacePanelBubble>

      {mode === "docked" ? (
        <WorkspacePanelDock
          width={resolvedPanelParameters.dockedPanelWidth}
          messages={messages}
          streaming={streaming}
          sessionMenu={resolvedSessionMenu}
          chatInputPlaceholder={resolvedPanelParameters.chatInputPlaceholder}
          emptyStateTitle={resolvedPanelParameters.emptyStateTitle}
          emptyStateDescription={resolvedPanelParameters.emptyStateDescription}
          onSubmitMessage={onSubmitMessage}
          onCollapse={() => setPanelMode("floating")}
          onClose={() => setPanelMode("closed")}
          onCommit={onCommit}
          onCreateSession={onCreateSession}
          newSessionLabel={resolvedPanelParameters.newSessionLabel}
          leadingActions={executorMenu}
          footerActions={repoMenu}
          diffs={diffs}
          commitLabel={resolvedPanelParameters.commitLabel}
          collapseLabel={resolvedPanelParameters.collapseLabel}
          closeLabel={resolvedPanelParameters.closeLabel}
          isSessionListOpen={isSessionListOpen}
          onCloseSessionList={() => setIsSessionListOpen(false)}
          sessionListTitle={resolvedPanelParameters.sessionListTitle}
          sessionListCloseLabel={resolvedPanelParameters.sessionListCloseLabel}
        />
      ) : null}
    </Box>
  );
};

